// Template for the generated menu category pages.
//
// Imported by tools/build-menu-pages.mjs (to write the pages) and by
// site/menu-pages.test.js (to assert the committed pages still match the data).
// Both must import the same module, or the drift test proves nothing.

export const GENERATED_BANNER =
  '<!-- GENERATED by tools/build-menu-pages.mjs from menu-data.js. Do not edit by hand — run `npm run build:menu`. -->';

const SITE = 'https://vaavkitchenandcaterers.com';

/** "Dinner 5" -> "dinner-5". Menu names are test-guaranteed unique, so slugs cannot collide. */
export function slug(name) {
  return String(name).toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
}

/** Escape a value for HTML text or a double-quoted attribute. */
export function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

const titleCase = s => String(s).charAt(0).toUpperCase() + String(s).slice(1);

/**
 * Per-category head copy. Distinct titles and descriptions, drawn from the real
 * dish vocabulary in menu-data.js — never templated boilerplate, which would read
 * as duplicate content across three near-identical pages.
 */
export const CATEGORY_META = {
  tiffin: {
    h1: 'Tiffin set menus',
    title: 'Tiffin Catering Menu — 20 Pure Veg Tiffin Sets | VAAV Kitchen',
    description:
      'All 20 VAAV tiffin set menus with every dish listed — idli, dosai, ghee pongal, medhu vadai, poori and chutney spreads for seemanthams, housewarmings and office breakfasts in Chennai.',
    ogTitle: 'Tiffin Catering Menu — 20 Pure Veg Sets | VAAV Kitchen, Chennai',
    ogDescription:
      '20 tiffin set menus, every dish listed. Idli, dosai, pongal, vadai and chutney spreads for morning functions across Chennai.'
  },
  lunch: {
    h1: 'Lunch set menus',
    title: 'Lunch Catering Menu — 20 Pure Veg Sappadu Sets | VAAV Kitchen',
    description:
      'All 20 VAAV lunch set menus with every dish listed — the banana-leaf sappadu with rice, sambar, rasam, vatha kulambu, poriyal, appalam and payasam, for weddings and receptions in Chennai.',
    ogTitle: 'Lunch Catering Menu — 20 Pure Veg Sappadu Sets | VAAV Kitchen',
    ogDescription:
      '20 lunch set menus, every dish listed. The classic banana-leaf sappadu, from a simple plate to a full feast.'
  },
  dinner: {
    h1: 'Dinner set menus',
    title: 'Dinner Catering Menu — 26 Pure Veg Dinner Sets | VAAV Kitchen',
    description:
      'All 26 VAAV dinner set menus with every dish listed — sweets, starters, biryani, bisi bele bath, kuzhambu and a full main course for wedding receptions in Chennai.',
    ogTitle: 'Dinner Catering Menu — 26 Pure Veg Sets | VAAV Kitchen, Chennai',
    ogDescription:
      '26 dinner set menus, every dish listed. Grand evening spreads with sweets, starters, biryani and a full main course.'
  }
};

const ORDER = ['tiffin', 'lunch', 'dinner'];

/** Rebuild the head: keep the source chrome byte-for-byte, swap only the per-page meta. */
function buildHead(sourceHead, url, meta) {
  let h = sourceHead
    // Drop the source page's JSON-LD; this page carries its own.
    .replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>\s*/g, '')
    .replace(/<title>[\s\S]*?<\/title>/, `<title>${esc(meta.title)}</title>`)
    .replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="${esc(meta.description)}">`)
    .replace(/<link rel="canonical" href="[^"]*">/, `<link rel="canonical" href="${url}">`)
    .replace(/<meta property="og:url" content="[^"]*">/, `<meta property="og:url" content="${url}">`)
    .replace(/<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${esc(meta.ogTitle)}">`)
    .replace(/<meta property="og:description" content="[^"]*">/, `<meta property="og:description" content="${esc(meta.ogDescription)}">`)
    .replace(/<meta name="twitter:title" content="[^"]*">/, `<meta name="twitter:title" content="${esc(meta.ogTitle)}">`)
    .replace(/<meta name="twitter:description" content="[^"]*">/, `<meta name="twitter:description" content="${esc(meta.ogDescription)}">`)
    .replace(/<link rel="prefetch"[^>]*>(<link rel="prefetch"[^>]*>)?/, '<link rel="prefetch" href="/menu/"><link rel="prefetch" href="/contact/">');
  return h.trimEnd();
}

/** BreadcrumbList + Menu JSON-LD for one category page. */
function buildSchema(catKey, data) {
  const url = `${SITE}/menu/${catKey}/`;
  const breadcrumb = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Home', item: `${SITE}/` },
      { '@type': 'ListItem', position: 2, name: 'Menu & Packages', item: `${SITE}/menu/` },
      { '@type': 'ListItem', position: 3, name: `${data.label} set menus`, item: url }
    ]
  };
  const menu = {
    '@context': 'https://schema.org',
    '@type': 'Menu',
    name: `VAAV Kitchen and Caterers — ${data.label} Set Menus`,
    inLanguage: 'en',
    url,
    provider: {
      '@type': 'FoodEstablishment',
      '@id': `${SITE}/#business`,
      name: 'VAAV Kitchen and Caterers'
    },
    hasMenuSection: [
      {
        '@type': 'MenuSection',
        name: data.label,
        url,
        hasMenuItem: data.menus.map(m => ({
          '@type': 'MenuItem',
          name: m.name,
          url: `${url}#${slug(m.name)}`
        }))
      }
    ]
  };
  return [breadcrumb, menu]
    .map(o => `<script type="application/ld+json">\n${JSON.stringify(o, null, 2)}\n</script>`)
    .join('\n');
}

/**
 * One <article> per set menu, with an id so /menu/dinner/#dinner-5 deep-links to it.
 *
 * `level` is the heading level for the set name. Category pages put sets
 * directly under the h1, so 2; occasion pages group them under a per-category
 * h2, so 3. The group label always sits one level below the name, and the
 * stylesheet keys off .set-name / .set-group rather than the element, because
 * the element is no longer fixed.
 */
function renderSet(m, level = 2) {
  const occ = (m.occasions || []).map(o => esc(titleCase(o))).join(', ');
  const total = (m.groups || []).reduce((n, g) => n + (g[1] ? g[1].length : 0), 0);
  const parts = [];
  parts.push(`      <article class="set" id="${slug(m.name)}">`);
  parts.push(`        <h${level} class="set-name">${esc(m.name)}</h${level}>`);
  parts.push(`        <p class="set-occ">${total} dishes${occ ? ` · Suited to: ${occ}` : ''}</p>`);
  for (const [label, items] of m.groups || []) {
    // Tiffin and lunch sets carry a single group literally labelled "Items";
    // printing that as a heading on 40 of 66 sets would be noise.
    const single = (m.groups || []).length === 1 && label === 'Items';
    if (!single) parts.push(`        <h${level + 1} class="set-group">${esc(label)}</h${level + 1}>`);
    parts.push('        <ul class="set-dishes">');
    for (const dish of items || []) parts.push(`          <li>${esc(dish)}</li>`);
    parts.push('        </ul>');
  }
  parts.push('      </article>');
  return parts.join('\n');
}

/**
 * Render one complete category page.
 * `chrome` is { head, top, bottom } extracted verbatim from site/menu/index.html,
 * so the CSP, nav, footer and scripts can never drift from the rest of the site.
 */
export function renderCategoryPage(catKey, data, chrome) {
  const meta = CATEGORY_META[catKey];
  if (!meta) throw new Error(`no CATEGORY_META for "${catKey}"`);
  const others = ORDER.filter(c => c !== catKey);
  const waHref =
    "https://wa.me/919655356333?text=Hello%20VAAV%20Kitchen%2C%20I'd%20like%20to%20enquire%20about%20" +
    encodeURIComponent(`${data.label.toLowerCase()} catering`) + '.';

  const main = [
    '<main id="main">',
    '  <section class="wrap sec">',
    `    <nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a> <span aria-hidden="true">/</span> <a href="/menu/">Menu &amp; Packages</a> <span aria-hidden="true">/</span> <span aria-current="page">${esc(data.label)}</span></nav>`,
    '    <div class="sec-head">',
    `      <p class="eyebrow">${esc(data.label)} &middot; ${esc(data.tamil)}</p>`,
    `      <h1>${esc(meta.h1)}</h1>`,
    `    </div>`,
    // data.note is authored HTML containing <strong>; it is the one value inserted raw.
    `    <p class="menu-intro">${data.note}</p>`,
    `    <p class="set-count"><b>${data.menus.length}</b> sets &middot; every dish listed below &middot; all customisable, including Jain and no onion-garlic.</p>`,
    '    <div class="set-list">',
    // Arrow, not a bare reference: Array#map passes the index as the second
    // argument, which would land in renderSet's `level` and emit <h0>, <h1>…
    data.menus.map(m => renderSet(m, 2)).join('\n'),
    '    </div>',
    '    <p class="set-more">Mix and match across any set — we tailor the spread to your event. <a href="/menu/">Browse the menus one at a time</a>, or see every ' +
      others.map(c => `<a href="/menu/${c}/">${esc(CATEGORY_META[c].h1.replace(' set menus', ''))} set</a>`).join(' and every ') +
      '.</p>',
    `    <p class="set-cta"><a class="btn" data-wa-context="${esc(data.label.toLowerCase())} catering" href="${waHref}" target="_blank" rel="noopener noreferrer">Ask for a ${esc(data.label.toLowerCase())} quote on WhatsApp</a></p>`,
    '  </section>',
    '</main>'
  ].join('\n');

  return [
    GENERATED_BANNER,
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    buildHead(chrome.head, `${SITE}/menu/${catKey}/`, meta),
    buildSchema(catKey, data),
    '</head>',
    chrome.top,
    main,
    chrome.bottom
  ].join('\n') + '\n';
}

// ---------------------------------------------------------------------------
// Occasion pages
//
// The same 66 sets, sliced by the occasion tags already in menu-data.js
// instead of by category. Only two of the eight occasions are built: the
// others either collide with a page that exists (/services/ targets wedding
// and corporate, /corporate/ owns bulk meals) or overlap each other too
// heavily to be separate pages — wedding and reception share 26 of their 40
// sets. See the ADR in docs/decisions.md.
// ---------------------------------------------------------------------------

export const OCCASIONS = ['housewarming', 'seemantham'];

/**
 * Per-occasion page copy.
 *
 * `intro` is authored prose, inserted raw — it is the whole reason these pages
 * are not a re-listing of the category pages, so it has to say something the
 * category pages cannot. Every fact in it is already published on the site:
 * the 30/50 guest minimums and the Jain / no onion-garlic line both come from
 * the FAQ on /contact/.
 *
 * `title` and `description` take the set count rather than hardcoding it, so
 * the copy cannot go stale when a set is retagged in menu-data.js.
 */
export const OCCASION_META = {
  housewarming: {
    label: 'Housewarming',
    noun: 'housewarming',
    plural: 'housewarmings',
    h1: 'Housewarming catering menus',
    eyebrow: 'By occasion &middot; Housewarming',
    title: n => `Housewarming Catering Menu — ${n} Pure Veg Sets | VAAV Kitchen`,
    description: n =>
      `All ${n} VAAV set menus we cook for a housewarming, every dish listed — morning tiffin spreads of idli, dosai, ghee pongal and vadai, and full banana-leaf lunches. Pure veg, catered across Chennai, from 30 guests.`,
    ogTitle: n => `Housewarming Catering Menu — ${n} Pure Veg Sets | VAAV Kitchen`,
    ogDescription:
      'The tiffin and lunch sets we cook for housewarmings in Chennai, every dish listed. Pure veg, fully customisable.',
    intro:
      'A housewarming is a morning function, and the spread usually follows it — idli, dosai, ghee pongal and vadai with fresh chutney and hot sambar, served to a house full of relatives before the day gets long. For families who sit their guests down to a meal, the full banana-leaf sappadu is here too. <strong>From 30 guests for a tiffin spread and 50 for a full meal</strong>, and every set below is customisable, including Jain and no onion-garlic.'
  },
  seemantham: {
    label: 'Seemantham',
    noun: 'seemantham',
    plural: 'seemanthams',
    h1: 'Seemantham catering menus',
    eyebrow: 'By occasion &middot; Seemantham',
    title: n => `Seemantham Catering Menu — ${n} Pure Veg Sets | VAAV Kitchen`,
    description: n =>
      `All ${n} VAAV set menus we cook for a seemantham, every dish listed — tiffin spreads with a sweet, medhu vadai, chutney and sambar, plus full sappadu options. Pure veg, catered across Chennai, from 30 guests.`,
    ogTitle: n => `Seemantham Catering Menu — ${n} Pure Veg Sets | VAAV Kitchen`,
    ogDescription:
      'The tiffin and lunch sets we cook for a seemantham in Chennai, every dish listed. Pure veg, fully customisable.',
    intro:
      'A seemantham is a daytime function, so the spread is tiffin-led — a sweet to start, then idli, dosai, pongal and vadai with chutney and sambar, with the full banana-leaf sappadu for families who seat their guests for lunch. <strong>Every set in our seemantham list is a tiffin or a lunch spread; none is a dinner.</strong> From 30 guests for a tiffin spread and 50 for a full sappadu, and every set is customisable, including Jain and no onion-garlic.'
  }
};

/**
 * The sets tagged with one occasion, grouped by category, in menu order.
 * A category with no matching set is dropped entirely — seemantham has no
 * dinner set, and an empty heading over an empty list is worse than no
 * section at all.
 */
export function setsByCategory(menus, occKey) {
  return ORDER
    .map(cat => ({
      cat,
      label: menus[cat].label,
      total: menus[cat].menus.length,
      sets: menus[cat].menus.filter(m => (m.occasions || []).includes(occKey))
    }))
    .filter(group => group.sets.length > 0);
}

/** BreadcrumbList + Menu JSON-LD for one occasion page. */
function buildOccasionSchema(occKey, meta, groups) {
  const url = `${SITE}/menu/${occKey}/`;
  const breadcrumb = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Home', item: `${SITE}/` },
      { '@type': 'ListItem', position: 2, name: 'Menu & Packages', item: `${SITE}/menu/` },
      { '@type': 'ListItem', position: 3, name: `${meta.label} set menus`, item: url }
    ]
  };
  const menu = {
    '@context': 'https://schema.org',
    '@type': 'Menu',
    name: `VAAV Kitchen and Caterers — ${meta.label} Set Menus`,
    inLanguage: 'en',
    url,
    provider: {
      '@type': 'FoodEstablishment',
      '@id': `${SITE}/#business`,
      name: 'VAAV Kitchen and Caterers'
    },
    // Each section points at the category page it was drawn from, not at this
    // page: that is where the complete list of those sets lives.
    hasMenuSection: groups.map(g => ({
      '@type': 'MenuSection',
      name: `${g.label} sets for a ${meta.noun}`,
      url: `${SITE}/menu/${g.cat}/`,
      hasMenuItem: g.sets.map(m => ({
        '@type': 'MenuItem',
        name: m.name,
        url: `${url}#${slug(m.name)}`
      }))
    }))
  };
  return [breadcrumb, menu]
    .map(o => `<script type="application/ld+json">\n${JSON.stringify(o, null, 2)}\n</script>`)
    .join('\n');
}

/**
 * Render one complete occasion page.
 *
 * Takes the whole VAAV_MENUS object rather than a pre-filtered slice, so the
 * body and the schema are built from one pass over the data and cannot
 * disagree. Self-canonical, deliberately: a canonical pointing at
 * /menu/tiffin/ would deindex the page and defeat the point of having it.
 */
export function renderOccasionPage(occKey, menus, chrome) {
  const meta = OCCASION_META[occKey];
  if (!meta) throw new Error(`no OCCASION_META for "${occKey}"`);
  const groups = setsByCategory(menus, occKey);
  if (!groups.length) throw new Error(`no menu in menu-data.js is tagged "${occKey}"`);

  const url = `${SITE}/menu/${occKey}/`;
  const count = groups.reduce((n, g) => n + g.sets.length, 0);
  const others = OCCASIONS.filter(o => o !== occKey);
  const waHref =
    "https://wa.me/919655356333?text=Hello%20VAAV%20Kitchen%2C%20I'd%20like%20to%20enquire%20about%20" +
    encodeURIComponent(`${meta.noun} catering`) + '.';

  const sections = groups.map(g => {
    const lower = g.label.toLowerCase();
    return [
      `      <h2 class="set-section">${esc(g.label)} sets for a ${esc(meta.noun)}</h2>`,
      `      <p class="set-section-more">The ${g.sets.length} ${lower} ${g.sets.length === 1 ? 'set' : 'sets'} we cook for ${esc(meta.plural)}. <a href="/menu/${g.cat}/">See all ${g.total} ${lower} sets</a>.</p>`,
      '      <div class="set-list">',
      g.sets.map(m => renderSet(m, 3)).join('\n'),
      '      </div>'
    ].join('\n');
  });

  const main = [
    '<main id="main">',
    '  <section class="wrap sec">',
    `    <nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a> <span aria-hidden="true">/</span> <a href="/menu/">Menu &amp; Packages</a> <span aria-hidden="true">/</span> <span aria-current="page">${esc(meta.label)}</span></nav>`,
    '    <div class="sec-head">',
    `      <p class="eyebrow">${meta.eyebrow}</p>`,
    `      <h1>${esc(meta.h1)}</h1>`,
    '    </div>',
    // meta.intro is authored HTML containing <strong>; like data.note on the
    // category pages, it is the one value inserted raw.
    `    <p class="menu-intro">${meta.intro}</p>`,
    `    <p class="set-count"><b>${count}</b> sets &middot; every dish listed below &middot; all customisable, including Jain and no onion-garlic.</p>`,
    ...sections,
    '    <p class="set-more">Not seeing the shape of your function? <a href="/menu/">Browse all 66 sets one at a time</a>' +
      others.map(o => `, or see the sets we cook for a <a href="/menu/${o}/">${esc(OCCASION_META[o].noun)}</a>`).join('') +
      '. We tailor any set to your day.</p>',
    `    <p class="set-cta"><a class="btn" data-wa-context="${esc(meta.noun)} catering" href="${waHref}" target="_blank" rel="noopener noreferrer">Ask for a ${esc(meta.noun)} quote on WhatsApp</a></p>`,
    '  </section>',
    '</main>'
  ].join('\n');

  return [
    GENERATED_BANNER,
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    buildHead(chrome.head, url, {
      title: meta.title(count),
      description: meta.description(count),
      ogTitle: meta.ogTitle(count),
      ogDescription: meta.ogDescription
    }),
    buildOccasionSchema(occKey, meta, groups),
    '</head>',
    chrome.top,
    main,
    chrome.bottom
  ].join('\n') + '\n';
}
